/* Original PINA toolkit only. story.html deliberately does not load this revision. */
const V2=PINA_V2, V2_INFO={
 anchor:['A solution already named','A request can make one solution feel settled before the problem is understood.','“Build a dashboard” names a solution. It does not establish why work is being delayed.'],
 interest:['Interest','The outcome or need behind the stated request. It can often be met in more than one way.','A client asks for a workshop because they want teams to make consistent decisions.'],
 intended:['Intended reading','How a reader who accepts your meaning would understand the message.','“We will pilot the new process” is read as a limited trial.'],
 negotiated:['Negotiated reading','A reader accepts part of the message but adds a reservation from their own situation.','“Yes, a pilot makes sense, but our team needs time to learn the process.”'],
 oppositional:['Oppositional reading','A fair opposing reading challenges the meaning or the terms, rather than simply misunderstanding the words.','“This sounds like extra approval work being presented as help.”'],
 deductive:['Deductive reasoning','Apply an accepted rule to a particular case. The conclusion follows only if both the rule and the conditions hold.','If every public release needs approval, and this is a public release, it needs approval. Check both premises.'],
 inductive:['Inductive reasoning','Use repeated cases to suggest a pattern. The conclusion is provisional and limited by the cases.','Several teams reported duplicate requests. That suggests a pattern, but it does not establish that every team has the same problem.'],
 abductive:['Abductive reasoning','Compare plausible explanations for what you observe and choose the one that fits best for now.','Few people use a feature. Possible explanations include poor visibility, low relevance or difficulty using it.'],
 confirmation:['Confirmation bias','We tend to notice support for a preferred view and overlook challenges. Comparing another view and naming what would change your mind helps counter this.','If you think a screen is confusing, also look for people who use it successfully and ask what explains the difference.'],
 premortem:['Failure check / premortem','Imagine that the recommendation was implemented and failed. Work backwards to a plausible reason.','“The pilot failed because nobody had time to record the results.”'],
 power:['Power','The ability to shape, fund, approve or block this decision. It is about the decision, not a person’s worth.','A budget holder may have high power even if the change barely affects their daily work.'],
 interest_matrix:['Interest','How much the outcome matters to a group or affects its work.','A support team may have high interest because it will use the new process every day.'],
 hears:['What might they hear?','Write how this group might read your message, in their own voice. It is a possible reading to check.','A finance lead may hear: “This will cost more.”'],
 basis:['Named or inferred','Named means they told you. Inferred means it is your guess. For a directly observed action, say explicitly what you observed in the answer.','“I’m worried about losing time” is named. “They may be worried because they stopped replying” is an inference.'],
 batna:['BATNA / your plan B','What you will do if you cannot agree. Knowing your alternative helps you decide when to walk away.','If this supplier cannot meet the deadline, the team can run a smaller internal pilot.'],
 ethos:['Ethos','The speaker’s credibility and trustworthiness for this audience on this subject. A title alone may not establish it.','Name who ran the pilot and how the results can be checked.'],
 pathos:['Pathos','How the message connects with what the audience feels or values.','Acknowledge that the new process will take time to learn before asking staff to adopt it.'],
 logos:['Logos','The reasons and evidence connecting a claim to a conclusion.','If the claim is that the process saves time, show what was compared and how time was measured.'],
 weights:['The 100 points','The points show how much each E drives that side’s view, not whether the side feels good or bad.','Members may give emotion 50 because losing a family habit drives their reaction more than the price.'],
 stranger:['A real stranger test','Show the piece to someone without explaining it. Record what they actually say. AI can only simulate a possible reading and must label it.','Ask a person: “What do you think this screen is for?” Then record their words before adding context.'],
 priming:['Priming','An opening cue makes a particular idea more available to the audience. Use a relevant cue without hiding the evidence.','Open with a recognisable missed-request moment before showing a proposed intake process.'],
 framing:['Framing','The way you describe a problem highlights some aspects of it. Check whether the description is fair.','“Reduce missed requests” highlights an outcome. “Add another form” highlights a task.'],
 availability:['Availability','A vivid or recent example can feel more representative than it is. Check it against other relevant evidence.','A dramatic complaint is memorable. Compare it with the broader set of reports before generalising.'],
 representativeness:['Representativeness','A case that resembles a familiar type can be mistaken for a reliable basis for prediction. Check the relevant differences and base rates.','A pilot team looks like the wider organisation, but may have had more training and support.'],
 pitch8:['The ask','The decision you want a particular person to make, with a clear time and commitment.','“Will you approve a two-week pilot and name an owner by Friday?”'],
 adoption:['Adoption conditions','Scores describe what might make an idea easier or harder for people to take up. They are prompts for discussion, not validated measurements.','A useful tool can still score low on fit if it does not work with the team’s existing systems.']
};
Object.assign(V2_INFO,{
 anchoring:['Anchoring','The first number or proposal can shape later judgement. A concrete ask gives a starting point, but its justification still needs checking.','Ask for a two-week trial because that fits the review cycle, not merely because two weeks was the first number mentioned.'],
 lever0:['Reciprocity','People may want to return something genuinely useful they received. Increasing this lever means making the real help visible, without creating an obligation.','Offer a useful checklist before asking for feedback. Make it clear the help is theirs whether or not they reply.'],
 lever1:['Commitment and consistency','People may act in line with a commitment they freely made. Increase this only when that commitment actually exists.','Remind a team of its agreed pilot goal, then ask whether it still wants to take the next step.'],
 lever2:['Social proof','People look to relevant others when deciding. Increase this by showing true, relevant behaviour, not invented popularity.','Two comparable teams completed a pilot. Link the results and explain the limits of the comparison.'],
 lever3:['Liking','A respectful, familiar connection can help a message be heard. Increase warmth without inventing shared experiences or flattery.','Acknowledge the work your colleague contributed before asking for a review.'],
 lever4:['Authority','Relevant expertise can support a decision. Increase this by naming qualifications and checkable evidence, not just a title.','The accessibility specialist checked the prototype. Link the findings and say what was tested.'],
 lever5:['Scarcity','A genuine limit can matter to a choice. Increase this only when the limit is real and useful to know.','There are three funded pilot places because that is the support capacity. Do not invent a countdown.'],
 lever6:['Unity','A real shared identity can support cooperation. Increase this by naming an authentic common purpose while respecting disagreement.','We share responsibility for helping the support team. Ask which approach best serves that purpose.'],
 eq0:['Credibility','How believable is the speaker’s knowledge and evidence in this situation?','A pilot report names its method and limits, rather than only making a confident claim.'],
 eq1:['Reliability','Do actions and commitments match what the speaker promises?','The team delivered the last two agreed updates on time.'],
 eq2:['Intimacy','Does the audience feel safe raising concerns and sharing what matters?','Invite a private question and show that disagreement will be treated respectfully.'],
 eq3:['Self-orientation','How much does the message appear to serve the speaker rather than the audience? A higher score means more self-focus.','A proposal only describes how the speaker benefits, without addressing the audience’s costs.']
});
['Reduce the appeal to returning a favour; keep the help unconditional.','Rely less on an earlier commitment and ask whether it still fits.','Rely less on what others did and show the relevant evidence.','Use a more direct tone while remaining respectful.','Let the method and results carry more of the explanation.','Present the real limit without amplifying urgency.','Rely less on group identity and address the person’s own priorities.'].forEach((text,i)=>{V2_INFO['lever'+i][1]+=' Turn down: '+text;});
const V2_NAMES={'Frame Test':'Reasoning Test','Evidence Ladder':'Recommendation Ladder','Deal Table':'Negotiation Table','Value Case':'Adoption Check','Thread Check':'Story Check','Reasoned Review':'Decision Record','Power & Interest Matrix':'Stakeholder Lens'};
function v2Words(html){for(const [before,after] of Object.entries(V2_NAMES))html=html.replace(new RegExp(before,'gi'),after);return html;}
const v2Tool=id=>V2.tools[id],v2Key=(id,key)=>'s'+id+'_'+key,v2Value=(id,key)=>String(work[v2Key(id,key)]??'').trim(),v2Yes=(id,key)=>[true,'true','yes'].includes(work[v2Key(id,key)]);
const v2WorkHref=(id,step='context')=>id<7?`#make/${id}/${step}`:step==='output'?anyUrl(id,'draft'):step==='notes'?anyUrl(id,'notes'):anyUrl(id,'work',step==='context'?0:Number(step)+1);
const v2LearnHref=(id,step=0)=>id<7?`#story/${id}/${step}`:anyUrl(id,'learn',step);
const v2CaseHref=id=>id<7?`#case/${id}`:anyUrl(id,'case');
for(const [idText,t] of Object.entries(V2.tools)){
 const id=Number(idText),target=ANYTIME[id]||T[id];target.name=t.name;
 target.intro=t.purpose;target.output=t.result;target.when=t.purpose;
 if(STARTS[id])Object.assign(STARTS[id],{intro:t.purpose,when:t.purpose,out:t.result,next:''});
 if(T[id])T[id].tags=t.sources.map(k=>V2.sources[k].name);
 if(SOURCE_CONTENT[id])SOURCE_CONTENT[id].research=t.sources.map(k=>V2.sources[k].name).join(' · ');
 if(ANYTIME_SOURCE[id])ANYTIME_SOURCE[id].research=t.sources.map(k=>V2.sources[k].name).join(' · ');
 PIP_TOOLS[id]=[t.name,t.purpose,pipV2Specs(id)];
}
pipSpecs=id=>pipV2Specs(id);
STUDIO_METHOD_TAGS[2]=['Deductive reasoning','Inductive reasoning','Abductive reasoning','Confirmation bias'];
STUDIO_METHOD_TAGS[13]=['Ethics','Emotion','Economics'];
STUDIO_METHOD_TAGS[6]=['Advantage','Fit','Simplicity','Trial','Visibility'];STUDIO_METHOD_TAGS[14]=['Think','Feel','Care','Say','Do'];
const v2NativePlan=questionPlan;questionPlan=id=>V2.tools[id]?V2.tools[id].steps.map((s,i)=>({key:v2Key(id,s.fields?.[0]?.key||'source'),q:s.title,hint:s.why,part:s.part,group:i,fields:s.fields})):v2NativePlan(id);
const v2NativeSpecsRequest=pipRequest;pipRequest=function(action,body){return v2NativeSpecsRequest(action,action==='assist'?{...body,curriculum:2}:body);};
const v2NativePipResult=pipResult;pipResult=function(){let html=v2NativePipResult();if(pipState.replyTool===5)html=html.replace('Add selected answers to my project','Confirm selected parts and save').replace('Apply selected answers','Confirm selected parts and save');return v2Words(html);};
const v2NativeExample=projectExample;
projectExample=function(id){const old=v2NativeExample(id);const extra={
 0:{message:'We plan to pilot a shared request queue next month.',revision:'We propose a two-week trial with two teams. We will review the time it takes before deciding whether to expand.',changes:'Added the trial limit and the review point.'},
 2:{problem:'Requests are often duplicated. I think the main problem is unclear ownership.',rival:'Another view is that the team has too little capacity, even when ownership is clear.',other_ded:'If every urgent request has an owner but still waits, ownership alone may not be enough.',other_ind:'Check whether delays are common across owners, not just where ownership is missing.',other_abd:'Insufficient capacity could explain waiting even when ownership is clear.'},
 3:{source1:'One interview during the pilot review.',source2:'A survey of the pilot teams.',source3:'A two-week comparison using the same request categories.'},
 4:{piece:'The opening three slides of the request-queue proposal.',picture:'The before-and-after flow shows the change without the headings.',missing:'The owner is not visible on the proposed queue.',repair:'Show the assigned owner next to each request.'},
 5:{review:'Meeting notes: We agreed to trial a shared queue with two teams. Reason: duplicate requests need one visible owner. We rejected a company-wide launch because the evidence is limited. Still open: Maya will confirm the trial schedule by Friday.',reflection:'The support representative still needs time to explain training constraints.'},
 6:{idea:'A shared intake queue for two pilot teams.',a1:'4',a2:'3',a3:'2',a4:'5',a5:'3',repair:'Remove two setup steps before inviting more teams.',trial:'Two teams use one queue for two weeks, with a review before expansion.',measure:'Count duplicate requests and compare the time to first response.'},
 8:{hasask:'yes',fair1:true,fair2:true,fair3:true},
 9:{situation:'Agree which parts of a pilot the external partner will support.',boundary:'max',posture1:'Reactive lenient',posture2:'Strategic',posture3:'Avoid'},
 10:{mode:'draft'},11:{traps:'Hasty generalization',evidence:'Two pilot teams reported that they wanted to keep the workflow.'},
 12:{source:'Pitch a two-week shared-queue pilot to the operations sponsor.',p0:'Yesterday, the same urgent request reached three people and nobody knew who owned it.',p1:'Urgent requests are duplicated or missed, costing teams time.',p2:'The pilot review found repeated examples of unclear ownership. Check the source before presenting this.',p3:'Try one shared intake queue with two teams.',p4:'Each request gets an owner and a visible response status.',p5:'A small trial found fewer duplicates; we still need to check response time.',p6:'Two teams, one owner and two weeks of support.',p7:'Teams can see ownership and spend less time chasing duplicates.',p8:'Will you approve a two-week pilot and name an owner by Friday?'},
 13:{uethics:'The team sees a consistent process as fairer.',uemotion:'They are relieved to have clearer ownership.',ueconomics:'They expect less time spent on duplicate requests.',tethics:'Support staff want the added effort to be shared fairly.',temotion:'They are concerned about learning another process.',teconomics:'Training will take time away from current work.'},
 14:{decision:'Introduce a shared request queue. Explore the support team lead’s view.',think:'They may believe this will become permanent before the trial is reviewed.',think_basis:'inferred',feel_basis:'inferred',care_basis:'inferred',say_basis:'named',do_basis:'named',check:'Ask whether training time and the review point address their concern.'}
 }[id]||{};for(const [key,value]of Object.entries(extra))old[v2Key(id,key)]=value;return old;};
// Keep each practice project coherent and omit retired fields from new examples.
const V2_EXAMPLE_FIX={"0":{"mean":"Try a small change before deciding whether to expand it.","r1":"This is a limited trial with a review.","r2":"A trial sounds useful, but our team needs time to learn it.","r3":"This could add approval work while being described as help."},"2":{"ded":"If a request needs an owner and none is assigned, unclear ownership could explain duplicate responses.","ind":"Review repeated cases of duplication and whether an owner was named.","abd":"Unclear ownership could explain why several people answer the same request.","see":"Both ownership and capacity may matter. Compare them before selecting a solution.","wrong":"Requests with clear owners show the same duplication under a comparable workload.","then":"Audit a small set of requests, recording workload, ownership and duplication."},"3":{"act":"run a two-week shared-queue pilot with two teams","f1":"One team lead said that urgent requests reach several people.","f2":"Several staff reported unclear ownership.","f3":"A small pilot recorded fewer duplicate responses.","source1":"Fictional practice interview with a team lead.","source2":"Fictional practice survey of two pilot teams.","source3":"Fictional practice pilot. Use your actual result and method in real work.","r1":"1","r2":"2","r3":"4","pre":"Nobody had time to maintain the queue or review what happened.","gain":"clearer ownership and less duplicate effort","gap":"whether this works for teams handling different requests","change":"duplicate effort or response time gets worse under a comparable workload"},"4":{"thread":"Make one owner visible for each urgent request.","where":"The before-and-after flow shows who takes responsibility.","picture":"The flow shows fewer handoffs, but the assigned owner is hard to see.","stranger":"Not tested with a real person yet.","yes":"The brief promised clearer ownership without extra approval work.","c1":true,"c2":true,"c3":false,"c4":false,"c5":false},"5":{"dec":"Trial one shared queue with two teams.","why":"Make ownership visible and reduce duplicate requests.","not":"A company-wide launch; the evidence is limited.","open":"Maya will confirm a trial schedule by Friday."},"7":{"priority":"Operations lead and support team"},"8":{"fair1":false,"fair2":false,"fair3":false},"9":{"us2":"3","them2":"3"},"13":{"us":"Operations sponsor","them":"Support team","issue":"Introduce a shared request queue.","u0":"30","u1":"20","u2":"50","t0":"35","t1":"40","t2":"25","speak":"Let’s protect training time and review the workload together before deciding whether to expand."},"14":{"who":"The support team lead","feel":"They may feel cautious about another process change.","care":"They may value manageable workload and fair ownership.","say":"In this fictional example, they said: We need time to learn it.","do":"In this fictional example, they asked for a training slot before the pilot.","mine":"Clear ownership should reduce duplicate effort.","theirs":"I want to help, but my team needs time to learn this and a genuine review before it expands."}};
const v2PartialExample=projectExample;
projectExample=function(id){const base=v2PartialExample(id);for(const [key,value]of Object.entries(V2_EXAMPLE_FIX[id]||{}))base[v2Key(id,key)]=value;const allowed=new Set(Object.keys(pipV2Specs(id)));for(const f of v2Tool(id).steps.flatMap(s=>s.fields)){if(f.basis)allowed.add(f.key+'_basis');if(f.check)allowed.add(f.check);}return Object.fromEntries(Object.entries(base).filter(([key])=>allowed.has(key.slice(('s'+id+'_').length))));};
