 for(const [to,from]of [['s12_p1','s12_beat1'],['s12_p3','s12_beat3'],['s12_p5','s12_beat4'],['s12_p8','s12_beat5'],['s12_source','s12_beat0']])if(!work[to]&&work[from])work[to]=work[from];
 if(!work.s11_traps&&work.s11_trap)work.s11_traps=work.s11_trap;
 work.v2_migration=1;persist(WORK_KEY,work);
