function v2BuiltDraft(id){const t=v2Tool(id);return t.name+'\n'+meta.project+'\n\n'+v2Output(id)+'\n\nREADINGS\n'+t.sources.map(k=>V2.sources[k].name).join('\n')+(v2Value(id,'notes')?'\n\nADDITIONAL NOTES\n'+v2Value(id,'notes'):'');}
const v2NativeOutput=outputText;outputText=id=>V2.tools[id]?v2Output(id):v2NativeOutput(id);
const v2NativeBuilt=builtDraft;builtDraft=id=>V2.tools[id]?v2BuiltDraft(id):v2NativeBuilt(id);
const v2NativeAnyDraft=anytimeDraft;anytimeDraft=id=>V2.tools[id]?v2BuiltDraft(id):v2NativeAnyDraft(id);
function v2EarlierAnswers(id){const t=v2Tool(id),used=new Set([t.source,'output','draftbase','incoming','notes','situation','audience','purpose',...t.steps.flatMap(s=>(s.fields||[]).flatMap(f=>[f.key,f.key+'_basis',f.key+'_confirmed',f.check].filter(Boolean)))]);const entries=Object.entries(work).filter(([k,v])=>k.startsWith('s'+id+'_')&&!used.has(k.slice(('s'+id+'_').length))&&String(v).trim()&&!/^s13_f\d$/.test(k)&&!/^s12_p\d$/.test(k)&&!/_confirmed$/.test(k));return entries.length?`<details class="v2-legacy"><summary>Earlier answers kept from the previous flow</summary><p>These notes are kept. They have not been relabelled as answers to a different question.</p><dl>${entries.map(([k,v])=>`<dt>${esc(FIELD_LABELS[k]||k.replace(/^s\d+_/,'').replaceAll('_',' '))}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`:'';}
function v2StepFields(id,index){const t=v2Tool(id),step=t.steps[index];let html=step.fields.map(f=>v2FieldHtml(id,f)).join('');
 if(id===10&&index===2)html+=`<details class="v2-reading-card"><summary>Go deeper with the trust equation</summary><p>Trust = (credibility + reliability + intimacy) ÷ self-orientation. Compare the direction of a change rather than treating it as a measured fact.</p>${TRUST_EQUATION.map(([label,hint],i)=>v2FieldHtml(10,v2Field('eq'+i,label,hint,{type:'select',options:Array.from({length:10},(_,n)=>[String(n+1),String(n+1)])}))).join('')}<p data-v2-trust-equation>${trustEquation()}</p></details>`;
 if(id===8&&index===0)html+=`<div data-v2-ask-warning ${v2Value(8,'hasask')==='no'?'':'hidden'} class="v2-inline-notice">There is no action to consider yet. <a href="${hybridHref(0)}">Check the reading</a> or <a href="${hybridHref(10)}">check trust</a> instead.</div>`;
 if(id===9&&index===1)html=`<div class="v2-posture-grid">${[['High for us / low for them','Reactive strict'],['Low for us / high for them','Reactive lenient'],['High for both','Strategic'],['Low for both','Avoid']].map(([a,b])=>`<div><b>${a}</b><span>${b}</span></div>`).join('')}</div><p class="input-caption">Strategic means hold your need and respect the person: “Love the party idea, but I’ve got an exam on Monday. Could we do Friday instead?”</p>`+html;
 if(id===12)html=v2PitchRouteNote(index)+html;
 if(id===3&&index<3)html='<p class="input-caption">Someone said it and Many said it describe reports. We saw it and We tested it describe behaviour. Testing comes closest to proof, while still needing a good source.</p>'+html;
 return html;
}
function v2PitchRouteNote(n){const route=v2Value(12,'route');if(!route)return '';const fast={0:['Priming','Start with a relevant moment that makes the issue recognisable.','priming'],1:['Framing','Describe the problem in terms that fairly show what is at stake.','framing'],2:['Availability','Make the evidence concrete, and show that it is more than one vivid example.','availability'],5:['Representativeness','Show why the proof is relevant to this setting; resemblance alone is not enough.','representativeness'],8:['Anchoring','Make a concrete, justified ask. Avoid treating the first number as automatically correct.','anchoring']};const careful=['Facts first','Cost of doing nothing','Evidence for the decision','The decision to make','Costs and benefits','Expected value and uncertainty','Resources and terms','Expected gains and losses','Terms and walk-away'];if(route==='beh'&&fast[n]){const [title,text,help]=fast[n];return `<aside class="v2-route-note"><b>Fast route: ${title}</b>${v2InfoButton(12,'p'+n,title,help)}<p>${text}</p></aside>`;}return route==='rat'?`<aside class="v2-route-note"><b>Careful route: ${careful[n]}</b><p>Give the audience checkable detail for this part of the decision.</p></aside>`:'';}
function v2ContextHtml(id){const t=v2Tool(id);return `<div class="v2-field"><label for="v2-project-name">Project name</label><input id="v2-project-name" data-v2-project value="${esc(meta.project)}" maxlength="120"></div>${v2Value(id,'incoming')?`<details class="v2-reading-card" open><summary>Carried from your previous tool</summary><p>${esc(v2Value(id,'incoming'))}</p><button type="button" class="text-link" data-v2-use-incoming="${id}">Use this as my starting material</button></details>`:''}${v2FieldHtml(id,t.context)}${id===12?v2FieldHtml(id,v2Field('audience','Who is the pitch for?','Name who can make the decision.'))+v2FieldHtml(id,v2Field('route','Does your audience decide fast on gut feel, or weigh up the details?','This changes the guidance. It does not remove the need for honest evidence.',{type:'select',options:[['beh','Fast, on an initial impression'],['rat','Carefully, weighing the details']]})):''}${id===12&&v2Value(12,'incoming_trial')?`<section class="v2-reading-card"><h2>Small trial carried from Adoption Check</h2><p>${esc(v2Value(12,'incoming_trial'))}</p><button class="text-link" type="button" data-v2-use-trial>Use this in The ask</button></section>`:''}${id===3&&v2Value(3,'situation')?`<details class="v2-reading-card"><summary>The message carried into this recommendation</summary><p>${esc(v2Value(3,'situation'))}</p></details>`:''}<p class="input-caption">${id===5?'Ask Pip can sort the notes into four parts. You choose which suggestions to confirm and save.':'Your context stays with this tool. AI help is optional.'}</p>`;}
