 const t=v2Tool(id),isContext=screen==='context',isNotes=screen==='notes',isOutput=screen==='output';if(isOutput)return v2DraftPage(id);
 const index=Math.max(0,Math.min(t.steps.length-1,Number(screen)||0)),step=t.steps[index],part=isContext?0:step.part;
 meta.last=id;meta.studioProgress[id]={screen};saveMeta();
 const body=isContext?`<h1>${id===5?'Start with the meeting notes.':'Tell me about your situation.'}</h1>${v2ContextHtml(id)}`:isNotes?`<h1>Anything else to keep?</h1>${v2FieldHtml(id,v2Field('notes','Additional notes','Add a constraint or reminder, or go straight to your result.'))}`:`${index===0?`<div class="v2-problem-kind"><b>What kind of problem are we working on?</b><p>${esc(t.problem)}</p></div>${v2ReadingCard(id)}`:''}<p class="eyebrow">REFLECTION ${index+1} OF ${t.steps.length}</p><h1>${esc(step.title)}</h1>${v2StepFields(id,index)}`;
 const previous=isContext?hybridHref(id):isNotes?v2WorkHref(id,t.steps.length-1):index?v2WorkHref(id,index-1):v2WorkHref(id),next=isContext?v2WorkHref(id,0):isNotes?v2WorkHref(id,'output'):index===t.steps.length-1?v2WorkHref(id,'notes'):v2WorkHref(id,index+1);
 return shell(`<div class="chapter-top"><h2 class="working-breadcrumb">${esc(t.name)}</h2><div class="chapter-tools">${restartButton(id)}</div></div><section class="make-spread clarity-work v2-workspace" data-v2-work="${id}" data-pip-workspace="${id}" data-v2-screen="${esc(screen)}"><aside class="conversation-pip"><div class="v2-live" data-v2-map="${id}" data-v2-map-part-active="${part}">${v2Map(id,'work',part)}</div></aside><article class="conversation-work" tabindex="0" aria-label="Project questions">${exampleButton(id)}<div class="v2-answer-sheet">${body}</div>${isNotes?'':mapSpeaker(isContext?t.purpose:step.why)}</article></section><div class="make-dock"><nav class="make-progress" aria-label="Working progress"><a href="${v2WorkHref(id)}" ${isContext?'class="active"':''}>Context</a><a href="${v2WorkHref(id,0)}" ${!isContext&&!isNotes?'class="active"':''}>Reflect</a><a href="${v2WorkHref(id,'notes')}" ${isNotes?'class="active"':''}>Notes</a><a href="${v2WorkHref(id,'output')}">Result</a></nav><div class="working-step-buttons"><a class="ink-button quiet" href="${previous}">← Go back</a><a class="ink-button primary" href="${next}">${isContext?'Let’s begin':isNotes?'Build my result':'Keep going'} →</a></div></div>`,'make-page v2-page');
