function v2NextTools(id){const route=meta.v2Route?.tools,at=route?.indexOf(id);return at>=0&&at<route.length-1?[route[at+1]]:v2Tool(id).next||[];}
function v2PitchPrompt(){return `Build a presentation for ${v2Value(12,'audience')||'[audience]'}. Use the nine beats in my chosen order below. Preserve the supplied facts, identify missing support, ask about missing beats and do not invent proof or decisions. Give a slide-by-slide outline ending with a clear ask.\n\n`+v2PitchOrder().map(n=>V2.beats[n][0]+': '+(v2Value(12,'p'+n)||'[missing: ask me]')).join('\n\n');}
