openMap=id=>{location.hash=v2LearnHref(id);};
const v2OriginalBind=bind;bind=function(){v2OriginalBind();v2MarkRoute();v2RefreshSecondary();const lesson=document.querySelector('[data-v2-learn]');if(lesson)v2ShowLesson(Number(lesson.dataset.v2Learn),Number(lesson.dataset.v2Part));else document.querySelectorAll('[data-v2-map] [data-map-step]').forEach(b=>b.setAttribute('aria-pressed','false'));};
// Revised answers use underscores for evidence basis and record confirmation.
// Read both old and new backups while retaining the existing format and storage keys.
document.querySelector('#import-file').addEventListener('change',async e=>{
 e.stopImmediatePropagation();const file=e.target.files[0];if(!file)return;
 try{
  if(file.size>2_000_000)throw Error('This file is too large for a PINA backup.');
  const data=JSON.parse(await file.text());
  if(data.format!=='pina-fieldguide'||data.version!==1||!data.work||typeof data.work!=='object'||Array.isArray(data.work)||!data.meta||typeof data.meta.project!=='string'||!Array.isArray(data.meta.pins))throw Error('Choose a valid PINA backup.');
  const clean={};for(const [key,value]of Object.entries(data.work)){
   if(key==='ledger'){if(!Array.isArray(value)||value.length>500||value.some(row=>!Array.isArray(row)||row.length!==6||row.some(cell=>typeof cell!=='string')))throw Error('The ledger format is invalid.');clean.ledger=value;}
   else if((/^s(?:[0-9]|1[0-4])_[a-zA-Z0-9_]+$/.test(key)||['v2_route_message','v2_migration'].includes(key))&&['string','number','boolean'].includes(typeof value))clean[key]=value;
  }
  if(!clean.ledger)clean.ledger=[['','','','','','']];
  if(!confirm('Import replaces the active project, answers, drafts and practice progress in this browser. Export the current work first if you need it. Continue?'))return;
  const nextMeta={project:data.meta.project.slice(0,120),displayName:typeof data.meta.displayName==='string'?data.meta.displayName.slice(0,60):'Aarshi',pins:[...new Set(data.meta.pins.filter(n=>Number.isInteger(n)&&n>=0&&n<7))],last:1,studioProgress:{}};
  for(let id=0;id<15;id++){const screen=data.meta.studioProgress?.[id]?.screen;if(['context','notes','output'].includes(screen)||(Number.isInteger(Number(screen))&&Number(screen)>=0&&Number(screen)<v2Tool(id).steps.length))nextMeta.studioProgress[id]={screen};}
  if(Array.isArray(data.meta.v2Route?.tools)&&data.meta.v2Route.tools.every(id=>Number.isInteger(id)&&id>=0&&id<15))nextMeta.v2Route={key:String(data.meta.v2Route.key||'saved'),tools:data.meta.v2Route.tools};
  const nextTrail={passed:[],answers:{},maps:{}};
  if(data.trail&&typeof data.trail==='object'){nextTrail.passed=Array.isArray(data.trail.passed)?data.trail.passed.filter(id=>Number.isInteger(id)&&id>=0&&id<15):[];for(let id=0;id<15;id++){const answer=data.trail.answers?.[id],map=data.trail.maps?.[id];if(Number.isInteger(answer)&&answer>=0&&answer<3)nextTrail.answers[id]=answer;if(Array.isArray(map))nextTrail.maps[id]=[...new Set(map.filter(n=>Number.isInteger(n)&&n>=0&&n<V2_LESSONS[id].length))];}}
  if(!persist(WORK_KEY,clean)||!persist(META_KEY,nextMeta)||!persist(TRAIL_KEY,nextTrail))throw Error('This browser could not save the imported work. The backup file is still safe.');
  work=clean;meta=nextMeta;trail=nextTrail;route();toast('Your notebook is restored.');
 }catch(error){toast(error.message||'Could not restore this backup.');}finally{e.target.value='';}
},true);
route();
